    border: 2px solid var(--magenta);
  }

</style>
</head>
<body>

<div class="poster-canvas">

  <!-- Image Layer -->
  <div class="concert-photo"></div>

  <!-- SVG Grain Generation -->
  <svg class="grit-overlay" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg">
    <filter id="noiseFilter">
      <feTurbulence type="fractalNoise" baseFrequency="0.95" numOctaves="3" stitchTiles="stitch"/>
    </filter>
    <rect width="100%" height="100%" filter="url(#noiseFilter)" />
  </svg>

  <!-- Graphic Elements Layer -->
  <div class="color-block block-cyan"></div>
  <div class="color-block block-magenta"></div>

  <!-- Type Layer -->
  <div class="typography">
    <h1 class="band-name name-bg">SONIC<br>DECAY</h1>
    <h1 class="band-name name-fg">SONIC<br>DECAY</h1>

    <div class="show-details">
      FRI OCT 24 // DOORS 8PM
    </div>

