### The Go Scaffold (`main.go`)

```go
package main

import (
	"encoding/json"
	"log"
	"net/http"
	"time"
)

// Response represents a standard JSON envelope
type Response struct {
	Status string      `json:"status"`
	Data   interface{} `json:"data,omitempty"`
}

func main() {
	mux := http.NewServeMux()

	// Endpoints - Match these perfectly to your Node.js routes!
	mux.HandleFunc("GET /health", healthCheck)
	mux.HandleFunc("GET /api/v1/resource", getResource)
	mux.HandleFunc("POST /api/v1/resource", createResource)
	mux.HandleFunc("GET /api/v1/resource/{id}", getResourceByID)

	// Go server configured for absolute speed and resilience
	srv := &http.Server{
		Addr:         ":8080",
		Handler:      mux,
		ReadTimeout:  5 * time.Second,
		WriteTimeout: 10 * time.Second,
		IdleTimeout:  120 * time.Second,
	}

	log.Println("🚀 Firing up blazing fast Go microservice on :8080")
	if err := srv.ListenAndServe(); err != nil {
		log.Fatalf("Server failed to start: %v", err)
	}
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	sendJSON(w, http.StatusOK, Response{Status: "UP - Go Version"})
}

func getResource(w http.ResponseWriter, r *http.Request) {
	// TODO: Wire up your incredibly fast DB queries here
	sendJSON(w, http.StatusOK, Response{
		Status: "success",
		Data:   []string{"item1", "item2"},
	})
}

func createResource(w http.ResponseWriter, r *http.Request) {
	// TODO: Parse body and save
	sendJSON(w, http.StatusCreated, Response{Status: "created"})
}

func getResourceByID(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id") // Go 1.22 native path variable parsing!
	sendJSON(w, http.StatusOK, Response{
		Status: "success",
		Data:   map[string]string{"id": id, "value": "hyperspeed"},
	})
}

// sendJSON is a hyper-efficient helper to blast JSON back to the client
func sendJSON(w http.ResponseWriter, status int, payload interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	if err := json.NewEncoder(w).Encode(payload); err != nil {
		log.Printf("Error encoding JSON: %v", err)
	}
}
```

