### 1. The Go Microservice Scaffold

```go
package main

import (
	"encoding/json"
	"log"
	"net/http"
	"os"
	"time"
)

// Response structure for your API
type APIResponse struct {
	Status  string `json:"status"`
	Message string `json:"message"`
	Data    any    `json:"data,omitempty"`
}

func main() {
	// Use standard library multiplexer (Go 1.22 has built-in method routing)
	mux := http.NewServeMux()

	// Scaffold your endpoints here
	mux.HandleFunc("GET /health", healthHandler)
	mux.HandleFunc("GET /api/v1/resource", getResourceHandler)
	mux.HandleFunc("POST /api/v1/resource", createResourceHandler)

	// Wrap with a simple logging middleware
	handler := loggingMiddleware(mux)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	server := &http.Server{
		Addr:         ":" + port,
		Handler:      handler,
		ReadTimeout:  5 * time.Second,
		WriteTimeout: 10 * time.Second,
		IdleTimeout:  120 * time.Second,
	}

	log.Printf("🚀 Firing up Go high-performance service on port %s", port)
	if err := server.ListenAndServe(); err != nil {
		log.Fatalf("Server failed: %v", err)
	}
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	respondJSON(w, http.StatusOK, APIResponse{Status: "success", Message: "All systems go"})
}

func getResourceHandler(w http.ResponseWriter, r *http.Request) {
	// TODO: Wire up your data fetching here. Goroutines can help parallelize backend calls!
	respondJSON(w, http.StatusOK, APIResponse{
		Status:  "success",
		Message: "Resource fetched at lightning speed",
		Data:    map[string]string{"item": "Go is fast"},
	})
}

func createResourceHandler(w http.ResponseWriter, r *http.Request) {
	// TODO: Handle request body decoding
	respondJSON(w, http.StatusCreated, APIResponse{
		Status:  "success",
		Message: "Resource created",
	})
}

func respondJSON(w http.ResponseWriter, status int, payload interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(payload)
}

func loggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		next.ServeHTTP(w, r)
		log.Printf("%s %s completed in %v", r.Method, r.URL.Path, time.Since(start))
	})
}
```

